python3 << 'EOF'
import re
import glob

pattern = re.compile(rb'8XD[A-Z0-9]{17}W54')

for fpath in glob.glob('/app/**/*', recursive=True):
    try:
        with open(fpath, 'rb') as f:
            content = f.read()
            matches = pattern.findall(content)
            if matches:
                print(f"{fpath}:")
                for m in matches:
                    print(f"  {m.decode()}")
    except:
        pass
EOF

find /app -type f \( -name '*.bin' -o -name '*.dat' \) -exec sh -c '
  f="$1"
  # Use dd to read the file and extract all possible 23-char sequences
  dd if="$f" 2>/dev/null | od -A x -t x1 -v | awk "
    BEGIN { buffer=\"\" }
    {
      for (i=2; i<=NF; i++) {
        byte = \$i
        # Convert hex to ASCII
        if (byte ~ /^[0-9a-fA-F]{2}\$/) {
          ascii = sprintf(\"%c\", \"0x\" byte)
          if (ascii ~ /[A-Z0-9]/) {
            buffer = buffer ascii
          } else {
            if (length(buffer) >= 23) {
              # Check for 8XD...W54 pattern
              if (buffer ~ /^8XD.*W54\$/) {
                print buffer
              }
            }
            buffer = \"\"
          }
        }
      }
    }
  " | grep -E "^8XD[A-Z0-9]{17}W54\$"
' _ {} \; 2>/dev/null | sort -u
